L000381	\title{
L000382	Imprints of asymptotic freedom on confining strings
L000383	}
L000384	
L000385	\author{Jan Albert$^{a}$, Alexandre Homrich$^{b,c}$}
L000386	\affiliation{$^{a}$Princeton Center for Theoretical Science, Princeton University, Princeton, NJ 08544, USA}
L000387	\affiliation{\vspace{0.1cm} $^{b}$ Kavli Institute for Theoretical Physics,
L000388	University of California, Santa Barbara, CA 93106, USA
L000389	\\$^{c}$ Walter Burke Institute for Theoretical Physics, Caltech, Pasadena, CA 91125, USA}
